  contabilidad: "M2.5 6.5h15v9h-15v-9Zm0 2.8h15M5.5 12.7h3",
  contenido: "M4 4.5h12v12H4v-12Zm0 3.3h12M7 3v3M13 3v3M6.5 11h2M11.5 11h2M6.5 14h2M11.5 14h2",
