function LoginGate({ onIngresar, onCancelar, pantallaInicial }) {
  const { oscuro, alternar } = useTema();
  const [pantalla, setPantalla] = useState(pantallaInicial || "login"); // login | registro
  const [nombreDespacho, setNombreDespacho] = useState("");
  const [nombre, setNombre] = useState("");
  const [email, setEmail] = useState("");
  const [contrasena, setContrasena] = useState("");
  const [error, setError] = useState("");
  const [enviando, setEnviando] = useState(false);

  useEffect(() => {
    ensureFonts();
  }, []);

  const cambiarPantalla = (nueva) => {
    setPantalla(nueva);
    setError("");
  };

  const crearDespacho = async () => {
    if (!nombreDespacho.trim() || !nombre.trim() || !email.trim() || !contrasena.trim()) return;
    const errorContrasena = validarContrasenaCliente(contrasena);
    if (errorContrasena) {
      setError(errorContrasena);
      return;
    }
    setEnviando(true);
    setError("");
    try {
      // Se crea el usuario de Auth desde el navegador (no con service_role)
      // para que Supabase mande el correo real de confirmación. Sin ese
      // correo confirmado, signUp no deja sesión activa todavía.
      const { data: signUpData, error: signUpError } = await supabase.auth.signUp({
        email: email.trim(),
        password: contrasena,
        options: { emailRedirectTo: typeof window !== "undefined" ? window.location.origin : undefined },
      });
      if (signUpError) throw signUpError;
      if (!signUpData.user) throw new Error("No se pudo crear la cuenta.");

      const response = await fetch("/api/despachos/crear", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ nombreDespacho: nombreDespacho.trim(), nombre: nombre.trim(), email: email.trim(), userId: signUpData.user.id }),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "No se pudo crear el despacho.");

      if (signUpData.session) {
        onIngresar();
      } else {
        setPantalla("registro-enviado");
      }
    } catch (e) {
      setError(e.message || "No se pudo crear el despacho. Intenta de nuevo.");
    }
    setEnviando(false);
  };

  const iniciarSesion = async () => {
    if (!email.trim() || !contrasena.trim()) return;
    setEnviando(true);
    setError("");
    const { error: loginError } = await supabase.auth.signInWithPassword({ email: email.trim(), password: contrasena });
    if (loginError) {
      setError("Correo o contraseña incorrectos.");
      setEnviando(false);
      return;
    }
    setEnviando(false);
    onIngresar();
  };

  const enviarRecuperacion = async () => {
    if (!email.trim()) return;
    setEnviando(true);
    setError("");
    const { error: recError } = await supabase.auth.resetPasswordForEmail(email.trim(), {
      redirectTo: typeof window !== "undefined" ? window.location.origin : undefined,
    });
    setEnviando(false);
    if (recError) {
      setError("No pudimos enviar el correo. Verifica la dirección e intenta de nuevo.");
      return;
    }
    setPantalla("recuperacion-enviada");
  };

  return (
    <div
      className={`${oscuro ? "drx-tema-oscuro" : "drx-tema-claro"} drx-glow`}
      style={{ minHeight: "100%", background: COLORS.bg, display: "flex", alignItems: "center", justifyContent: "center", padding: 24, position: "relative" }}
    >
      <GlobalStyle />
      <div style={{ position: "absolute", top: 20, right: 20 }}>
        <BotonTema oscuro={oscuro} onClick={alternar} />
      </div>
      <Card style={{ maxWidth: 420, width: "100%", textAlign: "center", position: "relative" }}>
        {onCancelar && (
          <button
            onClick={onCancelar}
            title="Volver"
            style={{ position: "absolute", top: 16, left: 16, background: "none", border: "none", cursor: "pointer", fontSize: 18, color: COLORS.muted, display: "flex", alignItems: "center", gap: 4 }}
          >
            ← <span style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5 }}>Volver</span>
          </button>
        )}
        <InsigniaPlataforma grande />
        <h1 style={{ fontFamily: "Inter, sans-serif", fontSize: 22, fontWeight: 800, textTransform: "uppercase", letterSpacing: 0.5, color: COLORS.headingText, margin: "0 0 4px" }}>
          {pantalla === "registro"
            ? "Registra tu despacho"
            : pantalla === "registro-enviado"
              ? "Confirma tu correo"
              : pantalla === "recuperar" || pantalla === "recuperacion-enviada"
                ? "Recuperar contraseña"
                : "Panel de gestión legal"}
        </h1>

        {pantalla === "registro" && (
          <div style={{ textAlign: "left" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, margin: "8px 0 16px" }}>
              Crea la cuenta de tu despacho — quedas como su Administrador y desde ahí creas a los demás usuarios y les das permisos. Tus datos quedan
              completamente separados de los de cualquier otro despacho.
            </p>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <Field label="Nombre del despacho">
                <input
                  className="drx-input"
                  style={inputStyle}
                  value={nombreDespacho}
                  onChange={(e) => setNombreDespacho(e.target.value)}
                  placeholder="Ej: García & Asociados"
                  autoFocus
                />
              </Field>
              <Field label="Tu nombre">
                <input className="drx-input" style={inputStyle} value={nombre} onChange={(e) => setNombre(e.target.value)} />
              </Field>
              <Field label="Correo">
                <input
                  type="email"
                  className="drx-input"
                  style={inputStyle}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Ej: felipe@cortesramirezabogados.com"
                />
              </Field>
              <Field label="Contraseña">
                <CampoContrasena valor={contrasena} onChange={setContrasena} />
                <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, margin: "4px 0 0" }}>
                  Mínimo 10 caracteres, combinando letras y números.
                </p>
              </Field>
            </div>
            {error && <p style={{ color: "#B42318", fontSize: 12.5, marginTop: 10, fontFamily: "Inter, sans-serif" }}>{error}</p>}
            <button
              className="drx-btn-primary"
              style={{ ...buttonPrimary, width: "100%", marginTop: 16 }}
              onClick={crearDespacho}
              disabled={enviando || !nombreDespacho.trim() || !nombre.trim() || !email.trim() || !contrasena.trim()}
            >
              {enviando ? "Creando…" : "Crear mi despacho"}
            </button>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, marginTop: 14, textAlign: "center" }}>
              ¿Ya tienes cuenta?{" "}
              <button
                onClick={() => cambiarPantalla("login")}
                style={{ background: "none", border: "none", color: COLORS.accentBright, cursor: "pointer", textDecoration: "underline", fontFamily: "Inter, sans-serif", fontSize: 11 }}
              >
                Inicia sesión
              </button>
            </p>
          </div>
        )}

        {pantalla === "registro-enviado" && (
          <div style={{ textAlign: "left" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, margin: "8px 0 16px" }}>
              Te enviamos un correo a <strong>{email}</strong> para confirmar tu cuenta. Ábrelo y confirma; después vuelve aquí e inicia sesión con tu
              correo y contraseña.
            </p>
            <button className="drx-btn-ghost" style={{ ...buttonGhost, width: "100%" }} onClick={() => cambiarPantalla("login")}>
              Ya confirmé, iniciar sesión
            </button>
          </div>
        )}

        {pantalla === "login" && (
          <div style={{ textAlign: "left" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, textAlign: "center", margin: "8px 0 18px" }}>Inicia sesión</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <Field label="Correo">
                <input
                  type="email"
                  className="drx-input"
                  style={inputStyle}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && iniciarSesion()}
                  autoFocus
                />
              </Field>
              <Field label="Contraseña">
                <CampoContrasena valor={contrasena} onChange={setContrasena} onEnter={iniciarSesion} autoFocus={!!email} />
              </Field>
            </div>
            {error && <p style={{ color: "#B42318", fontSize: 12.5, marginTop: 10, fontFamily: "Inter, sans-serif" }}>{error}</p>}
            <button
              className="drx-btn-primary"
              style={{ ...buttonPrimary, width: "100%", marginTop: 16 }}
              onClick={iniciarSesion}
              disabled={enviando || !email.trim() || !contrasena.trim()}
            >
              {enviando ? "Ingresando…" : "Ingresar"}
            </button>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, marginTop: 14, textAlign: "center" }}>
              <button
                onClick={() => cambiarPantalla("recuperar")}
                style={{ background: "none", border: "none", color: COLORS.accentBright, cursor: "pointer", textDecoration: "underline", fontFamily: "Inter, sans-serif", fontSize: 11 }}
              >
                ¿Olvidaste tu contraseña?
              </button>
              <br />
              ¿No tienes acceso? Pídele a tu administrador que te cree un usuario desde "Usuarios y permisos".
              <br />
              ¿Primera vez aquí?{" "}
              <button
                onClick={() => cambiarPantalla("registro")}
                style={{ background: "none", border: "none", color: COLORS.accentBright, cursor: "pointer", textDecoration: "underline", fontFamily: "Inter, sans-serif", fontSize: 11 }}
              >
                Crea tu despacho
              </button>
            </p>
          </div>
        )}

        {pantalla === "recuperar" && (
          <div style={{ textAlign: "left" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, margin: "8px 0 16px" }}>
              Escribe tu correo y te enviamos un enlace para poner una contraseña nueva.
            </p>
            <Field label="Correo">
              <input
                type="email"
                className="drx-input"
                style={inputStyle}
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && enviarRecuperacion()}
                autoFocus
              />
            </Field>
            {error && <p style={{ color: "#B42318", fontSize: 12.5, marginTop: 10, fontFamily: "Inter, sans-serif" }}>{error}</p>}
            <button
              className="drx-btn-primary"
              style={{ ...buttonPrimary, width: "100%", marginTop: 16 }}
              onClick={enviarRecuperacion}
              disabled={enviando || !email.trim()}
            >
              {enviando ? "Enviando…" : "Enviar enlace de recuperación"}
            </button>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, marginTop: 14, textAlign: "center" }}>
              <button
                onClick={() => cambiarPantalla("login")}
                style={{ background: "none", border: "none", color: COLORS.accentBright, cursor: "pointer", textDecoration: "underline", fontFamily: "Inter, sans-serif", fontSize: 11 }}
              >
                Volver a iniciar sesión
              </button>
            </p>
          </div>
        )}

        {pantalla === "recuperacion-enviada" && (
          <div style={{ textAlign: "left" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, margin: "8px 0 16px" }}>
              Listo — si ese correo tiene una cuenta, te llegó un enlace para poner una contraseña nueva. Ábrelo desde el mismo dispositivo y sigue las
              instrucciones.
            </p>
            <button
              className="drx-btn-ghost"
              style={{ ...buttonGhost, width: "100%" }}
              onClick={() => cambiarPantalla("login")}
            >
              Volver a iniciar sesión
            </button>
          </div>
        )}

        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 10.5, color: COLORS.muted, marginTop: 20, lineHeight: 1.5 }}>
          Inicio de sesión real con Supabase Auth: tu contraseña nunca se guarda en texto plano, viaja cifrada y la
          verifica el servidor.
        </p>
      </Card>
    </div>
  );
}

function UsuariosPermisosTab({ usuarioActual, onDespachoRenombrado }) {
  const usuarioActualId = usuarioActual.id;
  const { usuarios, crear: crearUsuario, actualizar } = useUsuariosDespacho();
  const [mostrarForm, setMostrarForm] = useState(false);
  const [nombre, setNombre] = useState("");
  const [email, setEmail] = useState("");
  const [contrasena, setContrasena] = useState("");
  const [rol, setRol] = useState("Asistente");
  const [error, setError] = useState("");
  const [creando, setCreando] = useState(false);
  const [nombreDespachoEdit, setNombreDespachoEdit] = useState(getNombreDespacho());
  const [editandoDespacho, setEditandoDespacho] = useState(false);
  const [guardandoDespacho, setGuardandoDespacho] = useState(false);

  const guardarNombreDespacho = async () => {
    if (!nombreDespachoEdit.trim()) return;
    setGuardandoDespacho(true);
    const { error: renombrarError } = await supabase.from("despachos").update({ nombre: nombreDespachoEdit.trim() }).eq("id", usuarioActual.despacho_id);
    setGuardandoDespacho(false);
    if (!renombrarError) {
      setDespachoActual(usuarioActual.despacho_id, nombreDespachoEdit.trim());
      onDespachoRenombrado?.(nombreDespachoEdit.trim());
      setEditandoDespacho(false);
    }
  };

  const crear = async () => {
    if (!nombre.trim() || !email.trim() || !contrasena.trim()) return;
    setCreando(true);
    setError("");
    try {
      const nuevoUsuario = await crearUsuario({ nombre: nombre.trim(), email: email.trim(), contrasena, rol });
      registrarAuditoria(usuarioActual, "crear_usuario", "usuario", nuevoUsuario?.id, { nombre: nombre.trim(), rol });
      setNombre("");
      setEmail("");
      setContrasena("");
      setRol("Asistente");
      setMostrarForm(false);
    } catch (e) {
      setError(e.message || "No se pudo crear el usuario.");
    }
    setCreando(false);
  };

  const cambiarPermiso = (u, seccionId, valor) => {
    const permisos = { ...(u.permisos || permisosPorDefecto(u.rol)), [seccionId]: valor };
    actualizar(u.id, { permisos });
    registrarAuditoria(usuarioActual, "cambiar_permiso", "usuario", u.id, { seccion: seccionId, valor, usuario: u.nombre });
  };

  const cambiarNotificacion = (u, categoriaId, valor) => {
    const notificaciones = { ...(u.notificaciones || notificacionesPorDefecto()), [categoriaId]: valor };
    actualizar(u.id, { notificaciones });
  };

  const [respaldando, setRespaldando] = useState(false);

  const descargarRespaldo = async () => {
    setRespaldando(true);
    try {
      const despachoId = usuarioActual.despacho_id;
      const tablas = ["clientes", "documentos", "casos", "chats", "app_settings"];
      const respaldo = { despacho: getNombreDespacho(), generadoEn: new Date().toISOString() };
      for (const tabla of tablas) {
        const { data, error } = await supabase.from(tabla).select("*").eq("despacho_id", despachoId);
        if (error) throw error;
        respaldo[tabla] = data || [];
      }
      const contenido = JSON.stringify(respaldo, null, 2);
      const blob = new Blob([contenido], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `respaldo-${getNombreDespacho().toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${new Date().toISOString().slice(0, 10)}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      registrarAuditoria(usuarioActual, "descargar_respaldo", "despacho", despachoId, {});
    } catch (e) {
      window.alert("No se pudo generar el respaldo. Intenta de nuevo en un momento.");
    }
    setRespaldando(false);
  };

  return (
    <div>
      <EncabezadoSeccion titulo="Usuarios y permisos" color="#6B7480" />
      <div
        style={{
          background: COLORS.accentSoft,
          border: "1px solid #C7D6EA",
          borderRadius: 10,
          padding: "12px 16px",
          marginBottom: 18,
          fontFamily: "Inter, sans-serif",
          fontSize: 12.5,
          color: COLORS.navy,
        }}
      >
        Solo tú, como Administrador, puedes crear usuarios y decidir qué puede ver cada uno.
      </div>

      <Card style={{ marginBottom: 20 }}>
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 600, color: COLORS.headingText, marginBottom: 4 }}>Nombre del despacho</p>
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, marginBottom: 10 }}>
          Aparece en el menú, los PDFs, los recibos y los mensajes de WhatsApp que manda la app.
        </p>
        {editandoDespacho ? (
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            <input
              className="drx-input"
              style={{ ...inputStyle, flex: 1, minWidth: 200 }}
              value={nombreDespachoEdit}
              onChange={(e) => setNombreDespachoEdit(e.target.value)}
            />
            <button className="drx-btn-primary" style={buttonPrimary} onClick={guardarNombreDespacho} disabled={guardandoDespacho || !nombreDespachoEdit.trim()}>
              {guardandoDespacho ? "Guardando…" : "Guardar"}
            </button>
            <button
              className="drx-btn-ghost"
              style={buttonGhost}
              onClick={() => {
                setNombreDespachoEdit(getNombreDespacho());
                setEditandoDespacho(false);
              }}
            >
              Cancelar
            </button>
          </div>
        ) : (
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10 }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 15, fontWeight: 700, color: COLORS.ink, margin: 0 }}>{getNombreDespacho()}</p>
            <button className="drx-btn-ghost" style={buttonGhost} onClick={() => setEditandoDespacho(true)}>
              Editar
            </button>
          </div>
        )}
      </Card>

      <Card style={{ marginBottom: 20, borderLeft: "4px solid #10B981" }}>
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 600, color: COLORS.headingText, marginBottom: 4 }}>🛡️ Respaldo de tus datos</p>
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, marginBottom: 12 }}>
          Descarga ahora mismo un archivo con TODA la información de tu despacho (clientes, documentos, casos y contenido) tal
          como está en este momento. Guárdalo en tu computador o en la nube (Google Drive, etc.). Recomendado: descárgalo
          cada semana o antes de cualquier cambio grande.
        </p>
        <button className="drx-btn-primary" style={{ ...buttonPrimary, background: "#10B981" }} onClick={descargarRespaldo} disabled={respaldando}>
          {respaldando ? "Generando respaldo…" : "⬇️ Descargar respaldo completo"}
        </button>
      </Card>

      <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 16 }}>
        <button className="drx-btn-primary" style={buttonPrimary} onClick={() => setMostrarForm((s) => !s)}>
          {mostrarForm ? "Cancelar" : "+ Nuevo usuario"}
        </button>
      </div>

      {mostrarForm && (
        <Card style={{ marginBottom: 16 }}>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            <Field label="Nombre">
              <input className="drx-input" style={inputStyle} value={nombre} onChange={(e) => setNombre(e.target.value)} />
            </Field>
            <Field label="Correo">
              <input type="email" className="drx-input" style={inputStyle} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Ej: novia@correo.com" />
            </Field>
            <Field label="Contraseña">
              <input type="password" className="drx-input" style={inputStyle} value={contrasena} onChange={(e) => setContrasena(e.target.value)} />
              <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, margin: "4px 0 0" }}>Mínimo 10 caracteres, combinando letras y números.</p>
            </Field>
            <Field label="Rol">
              <select className="drx-input" style={inputStyle} value={rol} onChange={(e) => setRol(e.target.value)}>
                <option>Administrador</option>
                <option>Abogado</option>
                <option>Asistente</option>
              </select>
            </Field>
          </div>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, color: COLORS.muted, marginTop: 10 }}>
            Los permisos se asignan según el rol y los puedes ajustar después en la lista de abajo.
          </p>
          {error && <p style={{ color: "#B42318", fontSize: 12.5, marginTop: 10, fontFamily: "Inter, sans-serif" }}>{error}</p>}
          <button
            className="drx-btn-primary"
            style={{ ...buttonPrimary, marginTop: 12 }}
            onClick={crear}
            disabled={creando || !nombre.trim() || !email.trim() || !contrasena.trim()}
          >
            {creando ? "Creando…" : "Crear usuario"}
          </button>
        </Card>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {usuarios.map((u) => {
          const permisos = u.permisos || permisosPorDefecto(u.rol);
          return (
            <Card key={u.id}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                <div>
                  <p style={{ fontFamily: "Inter, sans-serif", fontSize: 15, fontWeight: 700, color: COLORS.ink, margin: 0 }}>
                    {u.nombre} {u.id === usuarioActualId && <span style={{ color: COLORS.muted, fontWeight: 400, fontSize: 12 }}>(tú)</span>}
                  </p>
                  <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, margin: "2px 0 0" }}>
                    {u.email} · {u.rol}
                  </p>
                </div>
              </div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 12 }}>
                {SECCIONES_PERMISOS.map((s) => (
                  <label key={s.id} style={{ display: "flex", alignItems: "center", gap: 6, fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.inkSoft, cursor: "pointer" }}>
                    <input type="checkbox" checked={permisos[s.id] !== false} onChange={(e) => cambiarPermiso(u, s.id, e.target.checked)} disabled={u.rol === "Administrador"} />
                    {s.nombre}
                  </label>
                ))}
              </div>
              {u.rol === "Administrador" && (
                <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, marginTop: 8, fontStyle: "italic" }}>
                  Los administradores siempre ven todas las secciones.
                </p>
              )}

              <div style={{ borderTop: `1px solid ${COLORS.border}`, marginTop: 12, paddingTop: 10 }}>
                <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, fontWeight: 600, color: COLORS.muted, marginBottom: 8 }}>
                  🔔 Qué notificaciones recibe (campana)
                </p>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 12 }}>
                  {NOTIF_CATEGORIAS.map((n) => {
                    const notifs = u.notificaciones || notificacionesPorDefecto();
                    return (
                      <label key={n.id} style={{ display: "flex", alignItems: "center", gap: 6, fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.inkSoft, cursor: "pointer" }}>
                        <input type="checkbox" checked={notifs[n.id] !== false} onChange={(e) => cambiarNotificacion(u, n.id, e.target.checked)} />
                        {n.nombre}
                      </label>
                    );
                  })}
                </div>
              </div>
            </Card>
          );
        })}
      </div>

      <PapeleraPanel />
      <PanelAuditoria />
    </div>
  );
}

const TIPOS_PAPELERA = [
  { tipo: "clientes", etiqueta: "Clientes", campo: "nombre" },
  { tipo: "documentos", etiqueta: "Documentos", campo: "titulo" },
];

function PapeleraPanel() {
  const [abierto, setAbierto] = useState(false);
  const [cargado, setCargado] = useState(false);
  const [items, setItems] = useState({ clientes: [], documentos: [] });

  const cargar = useCallback(async () => {
    const [clientes, documentos] = await Promise.all([obtenerPapelera("clientes"), obtenerPapelera("documentos")]);
    setItems({ clientes, documentos });
    setCargado(true);
  }, []);

  useEffect(() => {
    if (abierto && !cargado) cargar();
  }, [abierto, cargado, cargar]);

  const restaurar = async (tipo, id) => {
    await restaurarDePapelera(tipo, id);
    cargar();
  };

  const borrarDefinitivo = async (tipo, id) => {
    if (!window.confirm("Esto borra el registro para siempre, sin poder recuperarlo. ¿Seguro?")) return;
    await eliminarDefinitivo(tipo, id);
    cargar();
  };

  const totalItems = items.clientes.length + items.documentos.length;

  return (
    <Card style={{ marginTop: 20 }}>
      <button
        onClick={() => setAbierto((a) => !a)}
        style={{ background: "none", border: "none", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center", width: "100%", padding: 0 }}
      >
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 15, fontWeight: 700, color: COLORS.ink, margin: 0 }}>
          🗑️ Papelera {cargado ? `(${totalItems})` : ""}
        </p>
        <span style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.muted }}>{abierto ? "Ocultar ▲" : "Ver ▼"}</span>
      </button>

      {abierto && (
        <div style={{ marginTop: 14 }}>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, marginBottom: 14 }}>
            Lo que se elimina desde Clientes o Firmar documentos queda aquí, no se borra de una. Puedes recuperarlo o borrarlo para siempre.
          </p>
          {TIPOS_PAPELERA.map(({ tipo, etiqueta, campo }) => (
            <div key={tipo} style={{ marginBottom: 16 }}>
              <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, fontWeight: 700, color: COLORS.headingText, marginBottom: 8 }}>{etiqueta}</p>
              {items[tipo].length === 0 && cargado && (
                <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, margin: 0 }}>Vacía.</p>
              )}
              <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                {items[tipo].map((r) => {
                  const dias = Math.floor((Date.now() - new Date(r.eliminado_en).getTime()) / 86400000);
                  return (
                    <div
                      key={r.id}
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        flexWrap: "wrap",
                        gap: 8,
                        background: COLORS.accentSoft,
                        border: `1px solid ${COLORS.border}`,
                        borderRadius: 8,
                        padding: "8px 12px",
                      }}
                    >
                      <div>
                        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, fontWeight: 600, color: COLORS.ink, margin: 0 }}>
                          {r.data?.[campo] || "(sin nombre)"}
                        </p>
                        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, margin: "2px 0 0" }}>
                          Eliminado hace {dias} día{dias !== 1 ? "s" : ""}
                        </p>
                      </div>
                      <div style={{ display: "flex", gap: 8 }}>
                        <button className="drx-btn-ghost" style={{ ...buttonGhost, padding: "5px 10px", fontSize: 12 }} onClick={() => restaurar(tipo, r.id)}>
                          Restaurar
                        </button>
                        <button
                          className="drx-btn-ghost"
                          style={{ ...buttonGhost, padding: "5px 10px", fontSize: 12, color: "#B42318", borderColor: "#F3B4AC" }}
                          onClick={() => borrarDefinitivo(tipo, r.id)}
                        >
                          Borrar para siempre
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
}

function PanelAuditoria() {
  const [registros, setRegistros] = useState([]);
  const [cargado, setCargado] = useState(false);
  const [abierto, setAbierto] = useState(false);

  useEffect(() => {
    if (!abierto || cargado) return;
    (async () => {
      const { data } = await supabase.from("auditoria").select("*").order("creado_en", { ascending: false }).limit(50);
      setRegistros(data || []);
      setCargado(true);
    })();
  }, [abierto, cargado]);

  const ETIQUETAS_ACCION = {
    crear_cliente: "creó al cliente",
    eliminar_cliente: "eliminó al cliente",
    registrar_pago: "registró un pago de",
    crear_usuario: "creó al usuario",
    cambiar_permiso: "cambió un permiso de",
    inicio_sesion: "inició sesión",
    descargar_respaldo: "descargó un respaldo completo",
  };

  return (
    <Card style={{ marginTop: 24 }}>
      <button
        onClick={() => setAbierto((a) => !a)}
        style={{ background: "none", border: "none", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center", width: "100%", padding: 0 }}
      >
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 15, fontWeight: 700, color: COLORS.ink, margin: 0 }}>📋 Auditoría (últimos 50 registros)</p>
        <span style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.muted }}>{abierto ? "Ocultar ▲" : "Ver ▼"}</span>
      </button>

      {abierto && (
        <div style={{ marginTop: 14 }}>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, marginBottom: 12 }}>
            Quién hizo qué y cuándo. Por ahora cubre creación/eliminación de clientes, pagos, creación de usuarios y cambios de permisos — se puede ampliar
            a más acciones cuando quieran.
          </p>
          {registros.length === 0 && cargado && <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.muted }}>Sin registros todavía.</p>}
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {registros.map((r) => (
              <p key={r.id} style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.inkSoft, margin: 0 }}>
                {new Date(r.creado_en).toLocaleString("es-CO", { dateStyle: "medium", timeStyle: "short" })} — <strong>{r.usuario_nombre || "Alguien"}</strong>{" "}
                {ETIQUETAS_ACCION[r.accion] || r.accion} {r.detalle?.nombre || r.detalle?.usuario || ""}
                {r.detalle?.valor ? ` (${formatoCOP(r.detalle.valor)})` : ""}
              </p>
            ))}
          </div>
        </div>
      )}
    </Card>
  );
}

function EstablecerContrasenaNueva({ onListo }) {
  const { oscuro, alternar } = useTema();
  const [contrasena, setContrasena] = useState("");
  const [confirmacion, setConfirmacion] = useState("");
  const [error, setError] = useState("");
  const [enviando, setEnviando] = useState(false);
  const [listo, setListo] = useState(false);

  const guardar = async () => {
    if (!contrasena.trim() || contrasena !== confirmacion) return;
    setEnviando(true);
    setError("");
    const { error: updateError } = await supabase.auth.updateUser({ password: contrasena });
    setEnviando(false);
    if (updateError) {
      setError(updateError.message?.toLowerCase().includes("password") ? "La contraseña debe tener al menos 10 caracteres, combinando letras y números." : "No pudimos guardar la contraseña. Intenta de nuevo.");
      return;
    }
    setListo(true);
  };

  return (
    <div
      className={`${oscuro ? "drx-tema-oscuro" : "drx-tema-claro"} drx-glow`}
      style={{ minHeight: "100%", background: COLORS.bg, display: "flex", alignItems: "center", justifyContent: "center", padding: 24, position: "relative" }}
    >
      <GlobalStyle />
      <div style={{ position: "absolute", top: 20, right: 20 }}>
        <BotonTema oscuro={oscuro} onClick={alternar} />
      </div>
      <Card style={{ maxWidth: 420, width: "100%", textAlign: "center" }}>
        <InsigniaPlataforma grande />
        <h1 style={{ fontFamily: "Inter, sans-serif", fontSize: 22, fontWeight: 800, textTransform: "uppercase", letterSpacing: 0.5, color: COLORS.headingText, margin: "0 0 4px" }}>
          Nueva contraseña
        </h1>
        {listo ? (
          <div style={{ textAlign: "left", marginTop: 16 }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, marginBottom: 16 }}>
              Tu contraseña quedó actualizada. Inicia sesión con la nueva.
            </p>
            <button className="drx-btn-primary" style={{ ...buttonPrimary, width: "100%" }} onClick={onListo}>
              Ir a iniciar sesión
            </button>
          </div>
        ) : (
          <div style={{ textAlign: "left", marginTop: 8 }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, marginBottom: 16 }}>Escribe tu contraseña nueva.</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <Field label="Contraseña nueva">
                <CampoContrasena valor={contrasena} onChange={setContrasena} autoFocus />
              </Field>
              <Field label="Confirmar contraseña">
                <CampoContrasena valor={confirmacion} onChange={setConfirmacion} onEnter={guardar} />
              </Field>
            </div>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, margin: "4px 0 0" }}>
              Mínimo 10 caracteres, combinando letras y números.
            </p>
            {confirmacion && contrasena !== confirmacion && (
              <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: "#B42318", marginTop: 8 }}>Las contraseñas no coinciden.</p>
            )}
            {error && <p style={{ color: "#B42318", fontSize: 12.5, marginTop: 10, fontFamily: "Inter, sans-serif" }}>{error}</p>}
            <button
              className="drx-btn-primary"
              style={{ ...buttonPrimary, width: "100%", marginTop: 16 }}
              onClick={guardar}
              disabled={enviando || !contrasena.trim() || contrasena !== confirmacion}
            >
              {enviando ? "Guardando…" : "Guardar contraseña"}
            </button>
          </div>
        )}
      </Card>
    </div>
  );
}

export default function App() {
  useEffect(() => {
    ensureFonts();
  }, []);

  const isFirmaView = typeof window !== "undefined" && window.location.hash.replace("#", "") === "firmar";
  const isPortalView = typeof window !== "undefined" && window.location.hash.replace("#", "") === "portal";
  const isPrivacidadView = typeof window !== "undefined" && window.location.hash.replace("#", "") === "privacidad";
  const [modoPublico, setModoPublico] = useState(isFirmaView);
  const [modoPortal, setModoPortal] = useState(isPortalView);
  const [usuarioActual, setUsuarioActual] = useState(null);
  const [sesionCargada, setSesionCargada] = useState(false);
  const [cambiandoUsuario, setCambiandoUsuario] = useState(false);
  const [tab, setTab] = useState("resumen");
  const [mostrarNotificaciones, setMostrarNotificaciones] = useState(false);
  const {
    count: notificaciones,
    firmasNuevas,
    clientesInactivos,
    pagosPendientes,
    contenidoPendiente,
    contenidoVencido,
    novedadesJudiciales,
    clientesSinRadicado,
    marcarFirmasVistas,
  } = useNotificacionesPanel(usuarioActual?.notificaciones);
  const { oscuro, alternar } = useTema();

  const [modoRecuperacion, setModoRecuperacion] = useState(false);
  const [mostrarLanding, setMostrarLanding] = useState(!isFirmaView && !isPortalView);
  const [pantallaLoginInicial, setPantallaLoginInicial] = useState("login");

  const cargarPerfilActual = useCallback(async (registrarLogin) => {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) {
      setDespachoActual(null);
      setUsuarioActual(null);
      return;
    }
    const { data: perfil } = await supabase.from("perfiles").select("*, despachos(nombre)").eq("id", user.id).maybeSingle();
    setDespachoActual(perfil?.despacho_id || null, perfil?.despachos?.nombre || "");
    const usuario = perfil ? { ...perfil, email: user.email, despachoNombre: perfil.despachos?.nombre || "" } : null;
    setUsuarioActual(usuario);
    if (registrarLogin && usuario) {
      registrarAuditoria(usuario, "inicio_sesion", "sesion", null, {});
    }
  }, []);

  useEffect(() => {
    (async () => {
      await cargarPerfilActual(false);
      setSesionCargada(true);
    })();
    const { data: suscripcion } = supabase.auth.onAuthStateChange((event) => {
      if (event === "PASSWORD_RECOVERY") {
        setModoRecuperacion(true);
        return;
      }
      cargarPerfilActual(event === "SIGNED_IN");
    });
    return () => suscripcion.subscription.unsubscribe();
  }, [cargarPerfilActual]);

  const iniciarSesion = () => {
    setCambiandoUsuario(false);
  };

  const cerrarSesion = useCallback(async () => {
    await supabase.auth.signOut();
    setCambiandoUsuario(false);
  }, []);

  const [avisoInactividad, setAvisoInactividad] = useState(false);
  useCierreSesionPorInactividad(!!usuarioActual && !modoPublico && !modoPortal, cerrarSesion, setAvisoInactividad);

  if (modoPublico) {
    return (
      <div style={{ background: COLORS.bg, minHeight: "100%" }}>
        <GlobalStyle />
        <VistaFirma />
        <p style={{ textAlign: "center", paddingBottom: 24 }}>
          <button
            onClick={() => setModoPublico(false)}
            style={{ background: "none", border: "none", color: COLORS.muted, textDecoration: "underline", cursor: "pointer", fontFamily: "Inter, sans-serif", fontSize: 12 }}
          >
            Volver al panel del despacho
          </button>
        </p>
      </div>
    );
  }

  if (modoPortal) {
    return (
      <div style={{ background: COLORS.bg, minHeight: "100%" }}>
        <GlobalStyle />
        <VistaPortalCliente />
        <p style={{ textAlign: "center", paddingBottom: 24 }}>
          <button
            onClick={() => setModoPortal(false)}
            style={{ background: "none", border: "none", color: COLORS.muted, textDecoration: "underline", cursor: "pointer", fontFamily: "Inter, sans-serif", fontSize: 12 }}
          >
            Volver al panel del despacho
          </button>
        </p>
      </div>
    );
  }

  if (isPrivacidadView) {
    return <PoliticaPrivacidad />;
  }

  if (!sesionCargada) {
    return <div style={{ background: COLORS.bg, minHeight: "100%" }} />;
  }

  if (modoRecuperacion) {
    return (
      <EstablecerContrasenaNueva
        onListo={async () => {
          await supabase.auth.signOut();
          setModoRecuperacion(false);
        }}
      />
    );
  }

  if (!usuarioActual && mostrarLanding) {
    return (
      <LandingPage
        onRegistrar={() => {
          setPantallaLoginInicial("registro");
          setMostrarLanding(false);
        }}
        onIniciarSesion={() => {
          setPantallaLoginInicial("login");
          setMostrarLanding(false);
        }}
      />
    );
  }

  if (!usuarioActual || cambiandoUsuario) {
    return (
      <LoginGate
        onIngresar={iniciarSesion}
        onCancelar={usuarioActual ? () => setCambiandoUsuario(false) : () => setMostrarLanding(true)}
        pantallaInicial={pantallaLoginInicial}
      />
    );
  }

  const irADocumentos = () => {
    setTab("documentos");
    setMostrarNotificaciones(false);
  };
  const irAClientes = () => {
    setTab("clientes");
    setMostrarNotificaciones(false);
  };
  const irAContenido = () => {
    setTab("contenido");
    setMostrarNotificaciones(false);
  };
  const irAVigilancia = () => {
    setTab("vigilancia");
    setMostrarNotificaciones(false);
  };

  const puedeVer = (seccionId) => {
    if (usuarioActual.rol === "Administrador") return true;
    const permisos = usuarioActual.permisos || permisosPorDefecto(usuarioActual.rol);
    return permisos[seccionId] !== false;
  };

  return (
    <div className={oscuro ? "drx-tema-oscuro" : "drx-tema-claro"} style={{ background: COLORS.bg, minHeight: "100%", display: "flex" }}>
      <GlobalStyle />

      <div
        style={{
          width: 250,
          flexShrink: 0,
          background: COLORS.navy,
          borderRight: `3px solid ${COLORS.accentBright}`,
          display: "flex",
          flexDirection: "column",
          padding: "24px 16px",
          position: "sticky",
          top: 0,
          height: "100vh",
          overflowY: "auto",
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "4px 6px 20px", marginBottom: 20, borderBottom: "1px solid rgba(255,255,255,0.08)" }}>
          <div style={{ display: "inline-flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
            <div style={{ width: 40, height: 40, borderRadius: 11, background: "#FFFFFF", display: "flex", alignItems: "center", justifyContent: "center", color: COLORS.navy, flexShrink: 0 }}>
              <IconoNomos size={22} />
            </div>
            <span style={{ fontFamily: "Inter, sans-serif", fontSize: 20, fontWeight: 800, letterSpacing: 1.5, color: "#FFFFFF", lineHeight: 1 }}>Nomos</span>
          </div>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 600, color: "#D7E2F1", margin: 0, lineHeight: 1.15, textAlign: "center" }}>
            {getNombreDespacho()}
          </p>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 8, flex: 1 }}>
          {puedeVer("resumen") && (
            <SidebarButton active={tab === "resumen"} onClick={() => setTab("resumen")} color="#2F80ED" icono="resumen">
              Resumen
            </SidebarButton>
          )}
          {puedeVer("clientes") && (
            <SidebarButton active={tab === "clientes"} onClick={() => setTab("clientes")} color="#14B8A6" icono="clientes">
              Clientes
            </SidebarButton>
          )}
          {puedeVer("vigilancia") && (
            <SidebarButton active={tab === "vigilancia"} onClick={() => setTab("vigilancia")} color="#F5A524" icono="vigilancia">
              Vigilancia judicial
            </SidebarButton>
          )}
          {puedeVer("contabilidad") && (
            <SidebarButton active={tab === "contabilidad"} onClick={() => setTab("contabilidad")} color="#F43F5E" icono="contabilidad">
              Contabilidad
            </SidebarButton>
          )}
          {puedeVer("contenido") && (
            <SidebarButton active={tab === "contenido"} onClick={() => setTab("contenido")} color="#8B5CF6" icono="contenido">
              Calendario de contenido
            </SidebarButton>
          )}
          {puedeVer("documentos") && (
            <SidebarButton active={tab === "documentos"} onClick={irADocumentos} color="#10B981" icono="documentos">
              Firmar documentos
            </SidebarButton>
          )}
          {puedeVer("reportes") && (
            <SidebarButton active={tab === "reportes"} onClick={() => setTab("reportes")} color="#0EA5E9" icono="reportes">
              Reportes
            </SidebarButton>
          )}
          {usuarioActual.rol === "Administrador" && (
            <SidebarButton active={tab === "usuarios"} onClick={() => setTab("usuarios")} color="#6B7480" icono="usuarios">
              Usuarios y permisos
            </SidebarButton>
          )}
        </div>

        <div style={{ borderTop: "1px solid #3A5A82", paddingTop: 14, marginTop: 14 }}>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: "#D7E2F1", margin: 0 }}>
            👤 <strong style={{ color: "#FFFFFF" }}>{usuarioActual.nombre}</strong>
          </p>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, color: "#9FB6D6", margin: "2px 0 10px" }}>{usuarioActual.rol}</p>
          <div style={{ display: "flex", gap: 12 }}>
            <button
              onClick={() => setCambiandoUsuario(true)}
              style={{ background: "none", border: "none", color: "#9FB6D6", fontSize: 11.5, cursor: "pointer", fontFamily: "Inter, sans-serif", textDecoration: "underline" }}
            >
              Cambiar de usuario
            </button>
            <button
              onClick={cerrarSesion}
              style={{ background: "none", border: "none", color: "#9FB6D6", fontSize: 11.5, cursor: "pointer", fontFamily: "Inter, sans-serif", textDecoration: "underline" }}
            >
              Cerrar sesión
            </button>
          </div>
        </div>
      </div>

      <div style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column" }}>
        <div
          style={{
            background: COLORS.panel,
            borderBottom: `1px solid ${COLORS.border}`,
            padding: "16px 28px",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            gap: 10,
            position: "sticky",
            top: 0,
            zIndex: 20,
          }}
        >
          <BuscadorGlobal onIr={setTab} />
          <div style={{ display: "flex", alignItems: "center", gap: 10, flexShrink: 0 }}>
            <button
              onClick={() => setMostrarNotificaciones(true)}
              title="Notificaciones"
              style={{
                position: "relative",
                background: "transparent",
                border: `1px solid ${COLORS.border}`,
                borderRadius: 8,
                width: 38,
                height: 38,
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: COLORS.headingText,
              }}
            >
              <IconoCampana />
              {notificaciones > 0 && (
                <span
                  style={{
                    position: "absolute",
                    top: -6,
                    right: -6,
                    background: "#E24B4A",
                    color: "#FFFFFF",
                    borderRadius: 20,
                    fontSize: 10,
                    fontWeight: 700,
                    padding: "1px 5px",
                    fontFamily: "Inter, sans-serif",
                  }}
                >
                  {notificaciones}
                </span>
              )}
            </button>
            <button className="drx-btn-ghost" style={buttonGhost} onClick={() => setModoPublico(true)}>
              Ver vista del cliente ↗
            </button>
            <BotonTema oscuro={oscuro} onClick={alternar} />
          </div>
        </div>

        <div style={{ padding: "28px 28px 40px", flex: 1 }}>
          <div style={{ maxWidth: 760, margin: "0 auto" }}>
            {tab === "resumen" && puedeVer("resumen") && <ResumenTab nombre={usuarioActual.nombre} usuarioId={usuarioActual.id} onIr={setTab} />}
            {tab === "clientes" && puedeVer("clientes") && <ClientesTab usuarioActual={usuarioActual} />}
            {tab === "vigilancia" && puedeVer("vigilancia") && <VigilanciaTab />}
            {tab === "contabilidad" && puedeVer("contabilidad") && <ContabilidadTab usuarioActual={usuarioActual} />}
            {tab === "contenido" && puedeVer("contenido") && <ContenidoTab />}
            {tab === "documentos" && puedeVer("documentos") && <DocumentosTab />}
            {tab === "reportes" && puedeVer("reportes") && <ReportesTab />}
            {tab === "usuarios" && usuarioActual.rol === "Administrador" && (
              <UsuariosPermisosTab
                usuarioActual={usuarioActual}
                onDespachoRenombrado={(nuevoNombre) => setUsuarioActual((prev) => (prev ? { ...prev, despachoNombre: nuevoNombre } : prev))}
              />
            )}
          </div>
        </div>

        <div style={{ borderTop: `1px solid ${COLORS.border}`, background: COLORS.panel, padding: "20px 24px 16px" }}>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
            <InsigniaPlataforma />
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 700, color: COLORS.headingText, margin: "0 0 6px" }}>
              {getNombreDespacho()}
            </p>
            <p style={{ textAlign: "center", fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, margin: 0 }}>
              Nomos — desarrollado por <strong style={{ color: COLORS.headingText }}>Felipe Cortés Ramírez</strong>, CEO. Todos los derechos reservados.
            </p>
          </div>
        </div>
      </div>

      {mostrarNotificaciones && (
        <ModalNotificaciones
          firmasNuevas={firmasNuevas}
          clientesInactivos={clientesInactivos}
          pagosPendientes={pagosPendientes}
          contenidoPendiente={contenidoPendiente}
          contenidoVencido={contenidoVencido}
          novedadesJudiciales={novedadesJudiciales}
          clientesSinRadicado={clientesSinRadicado}
          onCerrar={() => setMostrarNotificaciones(false)}
          onMarcarVistas={marcarFirmasVistas}
          onIrADocumentos={irADocumentos}
          onIrAClientes={irAClientes}
          onIrAContenido={irAContenido}
          onIrAVigilancia={irAVigilancia}
        />
      )}

      {avisoInactividad && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(10,18,32,0.55)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            padding: 20,
            zIndex: 2000,
          }}
        >
          <Card style={{ maxWidth: 380, textAlign: "center" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 16, fontWeight: 700, color: COLORS.ink, marginBottom: 8 }}>
              ¿Sigues ahí?
            </p>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, marginBottom: 18, lineHeight: 1.5 }}>
              Por seguridad, tu sesión está a punto de cerrarse por inactividad — útil si usas un computador compartido
              en el despacho. Mueve el mouse o haz clic para seguir conectado.
            </p>
            <button className="drx-btn-primary" style={{ ...buttonPrimary, width: "100%" }} onClick={() => setAvisoInactividad(false)}>
              Seguir conectado
            </button>
          </Card>
        </div>
      )}
    </div>
  );
}
